    }
    __forceinline CTCBase* FindTC(long interfaceType)   // the lookup alone, result straight into a register
    {
        long type = interfaceType;
        CInterfaceMap* map = &m_interfaces;
        CInterfaceMap::SEntry* it = map->LowerBound(&type);
